[
    {
        "title": "找出已知点",
        "description": "题目告诉我们，直线 $y=kx+b$ 经过两点 $(1,4)$ 和 $(3,10)$。先把这两个点作为求参数的依据。",
        "bubbleText": "一次函数里，已知两点就很有用了，因为可以先求斜率 $k$，再求截距 $b$。",
        "bubblePos": {
            "x": 245,
            "y": 250
        }
    },
    {
        "title": "计算横向变化",
        "description": "两点的横坐标之差为 $\\Delta x=3-1=2$。",
        "bubbleText": "从点 $(1,4)$ 到点 $(3,10)$，向右走了 $2$ 格，这就是 $\\Delta x$。",
        "bubblePos": {
            "x": 255,
            "y": 280
        }
    },
    {
        "title": "计算纵向变化",
        "description": "两点的纵坐标之差为 $\\Delta y=10-4=6$。",
        "bubbleText": "同样地，纵坐标从 $4$ 变到 $10$，向上增加了 $6$，这就是 $\\Delta y$。",
        "bubblePos": {
            "x": 360,
            "y": 225
        }
    },
    {
        "title": "求斜率k",
        "description": "根据一次函数斜率公式，$k=\\frac{\\Delta y}{\\Delta x}=\\frac{6}{2}=3$。",
        "bubbleText": "斜率就是“上升多少 ÷ 向右多少”。这里是 $6\\div2=3$，所以 $k=3$。",
        "bubblePos": {
            "x": 570,
            "y": 220
        }
    },
    {
        "title": "代入求b",
        "description": "把点 $(1,4)$ 代入 $y=kx+b$，得 $4=3\\times1+b$，所以 $b=1$。",
        "bubbleText": "现在 $k$ 已经知道了，就把点坐标塞进式子里，剩下的未知数只有 $b$，很快就能算出 $b=1$。",
        "bubblePos": {
            "x": 575,
            "y": 355
        }
    },
    {
        "title": "写出函数式",
        "description": "因此，这个一次函数为 $y=3x+1$。",
        "bubbleText": "参数都找到了：斜率是 $3$，截距是 $1$，完整式子就是 $y=3x+1$。",
        "bubblePos": {
            "x": 380,
            "y": 520
        }
    },
    {
        "title": "求x为0时的y",
        "description": "当 $x=0$ 时，代入函数式 $y=3x+1$，得 $y=3\\times0+1=1$。",
        "bubbleText": "求 $x=0$ 时的值最简单，直接把 $x$ 换成 $0$ 就行，所以 $y=1$。",
        "bubblePos": {
            "x": 595,
            "y": 470
        }
    },
    {
        "title": "验算答案",
        "description": "验算：当 $x=1$ 时，$y=3\\times1+1=4$；当 $x=3$ 时，$y=3\\times3+1=10$，都符合已知点，所以答案正确。最终 $k=3$，$b=1$，且当 $x=0$ 时 $y=1$。",
        "bubbleText": "把结果代回去检查一下，两个点都对上了，说明我们求出的 $k=3$、$b=1$ 完全正确。",
        "bubblePos": {
            "x": 595,
            "y": 105
        }
    }
]
